    def countNumbersWithUniqueDigits(self, n: int) -> int:
        if n == 0:
            return 1
        if n == 1:
            return 10

        # Start with numbers from 0 to 9
        count = 10
        # For the first digit, we have 9 options (1-9)
        # For the second digit, we have 9 options (0-9 except the first digit)
