class Solution:
    def splitArray(self, nums: List[int], k: int) -> int:
        def canSplit(maxSum):
            currentSum = 0
            subarrays = 1
            for num in nums:
                if num > maxSum:
                    return False
                if currentSum + num > maxSum:
                    subarrays += 1
                    currentSum = num
                else:
                    currentSum += num
            return subarrays <= k

