    def findKthNumber(self, n: int, k: int) -> int:
        current = 1
        k -= 1  # Adjust k to be zero-indexed

        while k > 0:
            count = self.getCntNodes(current, n)
            if count <= k:
                current += 1
                k -= count
            else:
                current *= 10
                k -= 1
        return current

    def getCntNodes(self, current: int, n: int) -> int:
