class Solution:
    def islandPerimeter(self, grid: List[List[int]]) -> int:
        if not grid or not grid[0]:
            return 0

        rows, cols = len(grid), len(grid[0])
        perimeter = 0

        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == 1:
                    # Start with 4 sides
                    perimeter += 4

                    # Check the top neighbor
                    if i > 0 and grid[i-1][j] == 1:
