        for week in range(k):
            new_dp = [-1] * n
            for city in range(n):
                if dp[city] == -1:
                    continue
                for next_city in graph[city]:
                    new_dp[next_city] = max(new_dp[next_city], dp[city] + days[next_city][week])
            dp = new_dp

        return max(dp)
