class Solution:
    def countSubstrings(self, s: str) -> int:
        def expand_around_center(left: int, right: int) -> int:
            count = 0
            while left >= 0 and right < len(s) and s[left] == s[right]:
                count += 1
                left -= 1
                right += 1
            return count

        total_palindromes = 0
        for i in range(len(s)):
            # Odd length palindromes
            total_palindromes += expand_around_center(i, i)
            # Even length palindromes
            total_palindromes += expand_around_center(i, i + 1)

        return total_palindromes
```

This solution uses the "expand around center" technique to count all palindromic substrings in the given string `s`. It considers each character and each pair of consecutive characters as potential centers of palindromes and expands outwards as long as the substring remains a palindrome. The count of such palindromic substrings is accumulated and returned.

class Trie:
    def __init__(self):
        self.children: List[Trie | None] = [None] * 26
        self.ref: int = -1

    def insert(self, w: str, i: int):
        node = self
        for c in w:
            idx = ord(c) - ord("a")
            if node.children[idx] is None:
                node.children[idx] = Trie()
            node = node.children[idx]
        node.ref = i

    def search(self, w: str) -> int:
        node = self
        for c in w:
            idx = ord(c) - ord("a")
            if node.children[idx] is None:
                return -1
            node = node.children[idx]
            if node.ref != -1:
                return node.ref
        return -1


