# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def checkEqualTree(self, root: Optional[TreeNode]) -> bool:
        def get_total_sum(node):
            if not node:
                return 0
            return node.val + get_total_sum(node.left) + get_total_sum(node.right)

        def can_partition(node, total_sum):
            if not node:
                return 0, False

            left_sum, left_possible = can_partition(node.left, total_sum)
            if left_possible:
                return left_sum, True

            right_sum, right_possible = can_partition(node.right, total_sum)
            if right_possible:
                return right_sum, True

            current_sum = node.val + left_sum + right_sum
            if current_sum == total_sum // 2 and current_sum * 2 == total_sum:
                return current_sum, True

            return current_sum, False

        total_sum = get_total_sum(root)
        if total_sum % 2 != 0:
            return False

        _, result = can_partition(root.left, total_sum)
        if result:
            return True

        _, result = can_partition(root.right, total_sum)
        if result:
            return True

        return False
```

This solution first calculates the total sum of the tree. It then tries to find a subtree whose sum is exactly half of the total sum. The function `can_partition` is a recursive function that checks if such a subtree exists, while ensuring that the subtree is not the entire tree itself. This is achieved by calling `can_partition` separately on the left and right children of the root.

