class Solution:
    def smallestDistancePair(self, nums: List[int], k: int) -> int:
        # Sort the array to facilitate the two-pointer technique
        nums.sort()
        n = len(nums)

        # Helper function to count the number of pairs with distance <= mid
        def count_pairs(mid: int) -> int:
            count = 0
            left = 0
            for right in range(n):
                while nums[right] - nums[left] > mid:
                    left += 1
                count += right - left
            return count

        # Binary search for the smallest distance
        low, high = 0, nums[-1] - nums[0]
        while low < high:
            mid = (low + high) // 2
            if count_pairs(mid) < k:
                low = mid + 1
            else:
                high = mid
        return low
```

This solution uses binary search combined with a two-pointer technique to efficiently find the kth smallest distance pair. The array is first sorted, and then the number of pairs with a distance less than or equal to a given value is counted using two pointers. The binary search narrows down the possible distances until the kth smallest is found.

class Trie:
    def __init__(self):
        self.children: List[Optional[Trie]] = [None] * 26
        self.is_end = False

    def insert(self, w: str):
        node = self
        for c in w:
            idx = ord(c) - ord("a")
            if node.children[idx] is None:
                node.children[idx] = Trie()
            node = node.children[idx]
        node.is_end = True

