            while i < len(s):
                if s[i] == '(':
                    stack.append(defaultdict(int))
                    i += 1
                elif s[i] == ')':
                    top = stack.pop()
                    i += 1
                    j = i
                    while j < len(s) and s[j].isdigit():
                        j += 1
                    mult = int(s[i:j]) if j > i else 1
                    for elem, count in top.items():
                        stack[-1][elem] += count * mult
