            # Try to move left
            left = k
            while left > 0 and heights[left - 1] <= heights[left]:
                left -= 1
            while left < n - 1 and heights[left + 1] == heights[left]:
                left += 1

            if left < k:
                heights[left] += 1
                continue

            # Try to move right
