    def kthSmallestPrimeFraction(self, arr: List[int], k: int) -> List[int]:
        def count_and_find_mid(mid):
            count = 0
            j = 1
            numerator = 0
            denominator = 1
            for i in range(len(arr)):
                while j < len(arr) and arr[i] / arr[j] > mid:
                    j += 1
                if j == len(arr):
                    break
                count += (len(arr) - j)
