class Solution:
    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:
        from collections import defaultdict

        n = len(graph)
        out_degree = [0] * n
        reverse_graph = defaultdict(list)

        # Build the reverse graph and compute out-degrees
        for i in range(n):
            for j in graph[i]:
                reverse_graph[j].append(i)
                out_degree[i] += 1

        # Queue for nodes with out-degree 0
        queue = deque([i for i in range(n) if out_degree[i] == 0])
        safe_nodes = set(queue)

        # Process the queue
        while queue:
            node = queue.popleft()
            for neighbor in reverse_graph[node]:
                out_degree[neighbor] -= 1
                if out_degree[neighbor] == 0:
                    queue.append(neighbor)
                    safe_nodes.add(neighbor)

        return sorted(safe_nodes)
```

This solution uses the concept of reverse graph traversal and topological sorting to identify safe nodes. Here's a breakdown of the approach:

1. **Reverse Graph Construction**: We build a reverse graph where edges are reversed. We also compute the out-degree of each node in the original graph.

2. **Queue Initialization**: We initialize a queue with all terminal nodes (nodes with zero out-degree).

3. **Processing the Queue**: We process each node in the queue, decrementing the out-degree of its neighbors in the reverse graph. If a neighbor's out-degree becomes zero, it means all paths leading to it are safe, so we add it to the queue and mark it as a safe node.

4. **Result**: After processing, the set of safe nodes is sorted and returned. 

This approach ensures that we correctly identify all safe nodes in the graph.

class Solution:
    def hitBricks(self, grid: List[List[int]], hits: List[List[int]]) -> List[int]:
        m = len(grid)
        if m == 0:
            return []
        n = len(grid[0])
        n_cols = n
        virtual = m * n
        grid_copy = [row[:] for row in grid]
        is_brick = [False] * len(hits)

        for i in range(len(hits)):
            x, y = hits[i]
            if grid[x][y] == 1:
                is_brick[i] = True
                grid_copy[x][y] = 0  # Mark the hit as removed initially

        # DSU class definition
        class DSU:
            def __init__(self, size):
                self.parent = list(range(size + 1))
                self.size = [1] * (size + 1)

            def find(self, x):
                if self.parent[x] != x:
                    self.parent[x] = self.find(self.parent[x])
                return self.parent[x]

            def union(self, x, y):
                x_root = self.find(x)
                y_root = self.find(y)
                if x_root == y_root:
                    return
                if self.size[x_root] < self.size[y_root]:
                    x_root, y_root = y_root, x_root
                self.parent[y_root] = x_root
                self.size[x_root] += self.size[y_root]

        dsu = DSU(m * n)

        # Initialize the DSU based on the modified grid (grid_copy)
        for i in range(m):
            for j in range(n):
                if grid_copy[i][j] == 1:
                    current = i * n_cols + j
                    if i == 0:
                        dsu.union(current, virtual)
                    # Check left
                    if j > 0 and grid_copy[i][j - 1] == 1:
                        left = current - 1
                        dsu.union(current, left)
                    # Check above
                    if i > 0 and grid_copy[i - 1][j] == 1:
                        above = (i - 1) * n_cols + j
                        dsu.union(current, above)

        res = []
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        for idx in reversed(range(len(hits))):
            hit = hits[idx]
            x, y = hit
            if not is_brick[idx]:
                res.append(0)
                continue
            cell_id = x * n_cols + y
            grid_copy[x][y] = 1  # Re-add the brick

            initial_size = dsu.size[dsu.find(virtual)]

            current = cell_id
            # Union with the virtual node if in the first row
            if x == 0:
                dsu.union(current, virtual)

            # Check all four directions
            for dx, dy in directions:
                nx = x + dx
                ny = y + dy
                if 0 <= nx < m and 0 <= ny < n:
                    if grid_copy[nx][ny] == 1:
                        neighbor_id = nx * n_cols + ny
                        dsu.union(current, neighbor_id)

            final_size = dsu.size[dsu.find(virtual)]
            delta = final_size - initial_size
            cnt = delta - 1 if delta > 0 else 0
            res.append(cnt)

        # Reverse the result to match the original hits order
        return res[::-1]


Explanation:
To solve this problem, we can use the Union-Find (Disjoint Set Union) data structure. The idea is to first remove all the bricks that will be hit and then simulate the process of adding the bricks back in reverse order, checking how many bricks become stable in the process.

Here's the step-by-step approach:

1. **Remove all bricks that will be hit**: Temporarily set the cells in `hits` to 0.
2. **Identify stable bricks**: Use Union-Find to group all stable bricks. A brick is stable if it is connected to the top row or to another stable brick.
3. **Simulate adding bricks back in reverse order**: For each hit in reverse order, if there was a brick at that position, add it back and check if it makes any other bricks stable.
4. **Count the number of bricks that fall**: Each time a brick is added back, count how many new bricks become stable due to this addition.

Here is the complete implementation:

```python
class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [1] * size
        self.size = [1] * size

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])  # Path compression
        return self.parent[u]

    def union(self, u, v):
        rootU = self.find(u)
        rootV = self.find(v)
        if rootU != rootV:
            if self.rank[rootU] > self.rank[rootV]:
                self.parent[rootV] = rootU
                self.size[rootU] += self.size[rootV]
            elif self.rank[rootU] < self.rank[rootV]:
                self.parent[rootU] = rootV
                self.size[rootV] += self.size[rootU]
            else:
                self.parent[rootV] = rootU
                self.rank[rootU] += 1
                self.size[rootU] += self.size[rootV]

    def getSize(self, u):
        return self.size[self.find(u)]

class Solution:
    def hitBricks(self, grid: List[List[int]], hits: List[List[int]]) -> List[int]:
        m, n = len(grid), len(grid[0])
        DIRECTIONS = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        # Create a copy of the grid with all hits applied
        copy_grid = [row[:] for row in grid]
        for i, j in hits:
            copy_grid[i][j] = 0

        # Union-Find data structure
        uf = UnionFind(m * n + 1)  # +1 for the virtual top node
        top = m * n

        # Helper function to convert 2D coordinates to 1D
        def getIndex(i, j):
            return i * n + j

        # Connect all stable bricks to the virtual top node and to each other
        for j in range(n):
            if copy_grid[0][j] == 1:
                uf.union(getIndex(0, j), top)

        for i in range(m):
            for j in range(n):
                if copy_grid[i][j] == 1:
                    for dx, dy in DIRECTIONS:
                        ni, nj = i + dx, j + dy
                        if 0 <= ni < m and 0 <= nj < n and copy_grid[ni][nj] == 1:
                            uf.union(getIndex(i, j), getIndex(ni, nj))

        # Result array
        result = [0] * len(hits)

        # Reverse hits to simulate adding bricks back
        for k in range(len(hits) - 1, -1, -1):
            i, j = hits[k]
            if grid[i][j] == 0:
                continue

            # Number of stable bricks before adding this brick
            prev_size = uf.getSize(top)

            # Add the brick back
            copy_grid[i][j] = 1

            # Connect to the virtual top node if it's in the top row
            if i == 0:
                uf.union(getIndex(i, j), top)

            # Connect to adjacent bricks
            for dx, dy in DIRECTIONS:
                ni, nj = i + dx, j + dy
                if 0 <= ni < m and 0 <= nj < n and copy_grid[ni][nj] == 1:
                    uf.union(getIndex(i, j), getIndex(ni, nj))

            # Number of stable bricks after adding this brick
            curr_size = uf.getSize(top)

            # The number of new bricks that became stable
            result[k] = max(0, curr_size - prev_size - 1)

        return result
```

This solution efficiently handles the problem using Union-Find to manage the connectivity of bricks and determine stability. The time complexity is approximately \(O((m \times n + h) \alpha(m \times n))\), where \(h\) is the number of hits and \(\alpha\) is the inverse Ackermann function, which grows very slowly. The space complexity is \(O(m \times n)\) for the Union-Find data structure.

class Solution:
    def splitArraySameAverage(self, nums: List[int]) -> bool:
        n = len(nums)
        if n == 1:
            return False
        s = sum(nums)
        for i, v in enumerate(nums):
            nums[i] = v * n - s
        m = n >> 1
        vis = set()
        for i in range(1, 1 << m):
            t = sum(v for j, v in enumerate(nums[:m]) if i >> j & 1)
            if t == 0:
                return True
            vis.add(t)
        for i in range(1, 1 << (n - m)):
            t = sum(v for j, v in enumerate(nums[m:]) if i >> j & 1)
            if t == 0 or (i != (1 << (n - m)) - 1 and -t in vis):
                return True
        return False


