from collections import Counter
from typing import List

class Solution:
    def threeSumMulti(self, arr: List[int], target: int) -> int:
        MOD = 10**9 + 7
        count = Counter(arr)
        keys = sorted(count.keys())
        n = len(keys)
        result = 0

        # Case 1: all three numbers are the same
        if target % 3 == 0 and target // 3 in count:
            v = target // 3
            if count[v] >= 3:
                result += count[v] * (count[v] - 1) * (count[v] - 2) // 6
                result %= MOD

        # Case 2: two numbers are the same, one is different
        for v1 in keys:
            v2 = target - 2 * v1
            if v1 == v2:
                continue
            if v2 in count and count[v1] >= 2:
                result += count[v1] * (count[v1] - 1) // 2 * count[v2]
                result %= MOD

        # Case 3: all three numbers are different
        for i in range(n):
            for j in range(i + 1, n):
                v3 = target - keys[i] - keys[j]
                if v3 <= keys[j]:
                    continue
                if v3 in count:
                    result += count[keys[i]] * count[keys[j]] * count[v3]
                    result %= MOD

        return result
```

This solution efficiently counts the number of valid triplets `(i, j, k)` such that `i < j < k` and `arr[i] + arr[j] + arr[k] == target` using a combination of combinatorial counting and a hash map to store the frequency of each number in the array. The solution handles three distinct cases: when all three numbers are the same, when two numbers are the same and one is different, and when all three numbers are different.

class UnionFind:
    __slots__ = "p", "size"

    def __init__(self, n: int):
        self.p = list(range(n))
        self.size = [1] * n

    def find(self, x: int) -> int:
        if self.p[x] != x:
            self.p[x] = self.find(self.p[x])
        return self.p[x]

    def union(self, a: int, b: int) -> bool:
        pa, pb = self.find(a), self.find(b)
        if pa == pb:
            return False
        if self.size[pa] > self.size[pb]:
            self.p[pb] = pa
            self.size[pa] += self.size[pb]
        else:
            self.p[pa] = pb
            self.size[pb] += self.size[pa]
        return True

    def get_size(self, root: int) -> int:
        return self.size[root]


class Solution:
    def minMalwareSpread(self, graph: List[List[int]], initial: List[int]) -> int:
        n = len(graph)
        uf = UnionFind(n)
        for i in range(n):
            for j in range(i + 1, n):
                graph[i][j] and uf.union(i, j)
        cnt = Counter(uf.find(x) for x in initial)
        ans, mx = n, 0
        for x in initial:
            root = uf.find(x)
            if cnt[root] > 1:
                continue
            sz = uf.get_size(root)
            if sz > mx or (sz == mx and x < ans):
                ans = x
                mx = sz
        return min(initial) if ans == n else ans


