# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def flipEquiv(self, root1: Optional[TreeNode], root2: Optional[TreeNode]) -> bool:
        if not root1 and not root2:
            return True
        if not root1 or not root2 or root1.val != root2.val:
            return False

        # Check if children are equivalent without flipping
        without_flip = (self.flipEquiv(root1.left, root2.left) and
                        self.flipEquiv(root1.right, root2.right))

        # Check if children are equivalent with flipping
        with_flip = (self.flipEquiv(root1.left, root2.right) and
                     self.flipEquiv(root1.right, root2.left))

        return without_flip or with_flip
```

This solution checks if two binary trees are flip equivalent by recursively comparing their nodes. It considers both the cases where the children of a node are either not flipped or flipped to see if the trees can be made equivalent.

