        def backtrack(current_number, length):
            if length == n:
                result.append(current_number)
                return

            last_digit = current_number % 10

            # Add the next digit if it's valid
            if last_digit + k < 10:
                backtrack(current_number * 10 + (last_digit + k), length + 1)

