        if k > len(s):
            return 0

        count = 0
        window = {}

        # Initialize the first window
        for i in range(k):
            if s[i] in window:
                window[s[i]] += 1
            else:
                window[s[i]] = 1

        # Check the first window
        if len(window) == k:
            count += 1

