                left = nums[i - 1] if i > 0 else float('inf')
                right = nums[i + 1] if i < n - 1 else float('inf')
                target = min(left, right) - 1
                if nums[i] > target:
                    moves_odd += nums[i] - target

        return min(moves_even, moves_odd)
