from typing import List
from collections import defaultdict, deque

class Solution:
    def frogPosition(self, n: int, edges: List[List[int]], t: int, target: int) -> float:
        if n == 1:
            return 1.0

        # Build the graph
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        # BFS to calculate the probability
        queue = deque([(1, 1.0, 0)])  # (current node, current probability, current time)
        visited = set([1])

        while queue:
            current, prob, time = queue.popleft()

            # Get all unvisited neighbors
            neighbors = [neighbor for neighbor in graph[current] if neighbor not in visited]
            num_neighbors = len(neighbors)

            # If we reach the target
            if current == target:
                # If we have no more time or no more neighbors to jump to
                if time == t or not neighbors:
                    return prob
                else:
                    return 0.0

            # If we run out of time but haven't reached the target
            if time == t:
                continue

            # Explore neighbors
            for neighbor in neighbors:
                visited.add(neighbor)
                queue.append((neighbor, prob / num_neighbors, time + 1))

        return 0.0
```

This solution uses a breadth-first search (BFS) approach to traverse the tree and calculate the probability of the frog being on the target vertex after `t` seconds. The BFS ensures that we explore all possible paths the frog can take and calculate the probabilities accordingly. The frog's probability of being on a vertex is updated as it jumps to new vertices, and the algorithm checks if the target vertex is reached at the exact time `t` or if the frog is forced to stay on the target vertex because it has no more unvisited neighbors.

