from typing import List
import functools

class Solution:
    def minCost(self, houses: List[int], cost: List[List[int]], m: int, n: int, target: int) -> int:

        @functools.lru_cache(None)
        def dp(i, prev_color, groups):
            if i == m:
                return 0 if groups == target else float('inf')

            if houses[i] != 0:
                # If the house is already painted
                new_groups = groups + (1 if houses[i] != prev_color else 0)
                return dp(i + 1, houses[i], new_groups)
            else:
                # Try painting the house with each color
                min_cost = float('inf')
                for color in range(1, n + 1):
                    new_groups = groups + (1 if color != prev_color else 0)
                    min_cost = min(min_cost, cost[i][color - 1] + dp(i + 1, color, new_groups))
                return min_cost

        result = dp(0, 0, 0)
        return result if result != float('inf') else -1
```

### Explanation:
- The function `dp(i, prev_color, groups)` is a recursive function with memoization to avoid recalculating results for the same state.
  - `i`: The current house index.
  - `prev_color`: The color of the previous house.
  - `groups`: The number of neighborhoods formed so far.
- If `i == m`, we check if the number of neighborhoods is equal to `target`. If yes, return 0 (no additional cost). Otherwise, return infinity (invalid state).
- If the house `houses[i]` is already painted (`houses[i] != 0`), we calculate the new number of neighborhoods and proceed to the next house.
- If the house is not painted (`houses[i] == 0`), we try painting it with each possible color and calculate the minimum cost.
- The function `dp` is memoized using `functools.lru_cache` to store and reuse results of subproblems.
