    def numSubmat(self, mat: List[List[int]]) -> int:
        if not mat or not mat[0]:
            return 0

        m, n = len(mat), len(mat[0])
        # Create a helper array to store the number of consecutive 1s ending at each cell
        dp = [[0] * n for _ in range(m)]

        # Fill the dp array
