                    found_p = True
                if node == q:
                    found_q = True
                return node

            # If both left and right are not None, current node is the LCA
            if left and right:
                return node

            return left if left else right

        found_p, found_q = False, False
        lca = findLCA(root)

        # Ensure both p and q are found in the tree
        if found_p and found_q:
            return lca
        else:
            return None
