    def minSessions(self, tasks: List[int], sessionTime: int) -> int:
        n = len(tasks)
        # Precompute all possible subsets and their total times
        subset_times = [0] * (1 << n)
        for i in range(n):
            for mask in range(1 << i):
                subset_times[mask | (1 << i)] = subset_times[mask] + tasks[i]

