from typing import List
from sortedcontainers import SortedList

class Solution:
    def maxTaskAssign(self, tasks: List[int], workers: List[int], pills: int, strength: int) -> int:
        def can_assign(k):
            p = pills
            available_workers = SortedList(workers[-k:])
            for task in tasks[:k][::-1]:
                if not available_workers:
                    return False
                # Try to find a worker who can do the task without a pill
                worker = available_workers.bisect_left(task)
                if worker < len(available_workers):
                    available_workers.pop(worker)
                else:
                    # If no worker can do the task without a pill, use a pill
                    if p == 0:
                        return False
                    p -= 1
                    # Find a worker who can do the task with a pill
                    worker_with_pill = available_workers.bisect_left(task - strength)
                    if worker_with_pill < len(available_workers):
                        available_workers.pop(worker_with_pill)
                    else:
                        return False
            return True

        tasks.sort()
        workers.sort()
        left, right = 0, min(len(tasks), len(workers)) + 1
        while left < right:
            mid = (left + right) // 2
            if can_assign(mid):
                left = mid + 1
            else:
                right = mid
        return left - 1
```

This solution uses binary search to determine the maximum number of tasks that can be assigned. For each midpoint in the binary search, it checks if it's possible to assign that many tasks using the given workers and pills. The `can_assign` function uses a `SortedList` to efficiently find and remove workers who can complete the tasks, either with or without a pill.

