            supply = queue.popleft()
            for recipe in graph[supply]:
                indegree[recipe] -= 1
                # If all ingredients for a recipe are available, add it to the result and queue
                if indegree[recipe] == 0:
                    result.append(recipe)
                    queue.append(recipe)

