from collections import Counter
from typing import List

class Solution:
    def singleDivisorTriplet(self, nums: List[int]) -> int:
        count = Counter(nums)
        unique_nums = list(count.keys())
        n = len(unique_nums)
        result = 0

        # Iterate over all possible triplets (i, j, k)
        for i in range(n):
            for j in range(i, n):
                for k in range(j, n):
                    a, b, c = unique_nums[i], unique_nums[j], unique_nums[k]
                    total = a + b + c

                    # Check divisibility conditions
                    divisors = sum(total % x == 0 for x in [a, b, c])

                    if divisors == 1:
                        # Count permutations based on the number of unique elements
                        if i == j == k:
                            result += count[a] * (count[a] - 1) * (count[a] - 2) // 6
                        elif i == j:
                            result += count[a] * (count[a] - 1) // 2 * count[c]
                        elif j == k:
                            result += count[a] * count[b] * (count[b] - 1) // 2
                        elif i == k:
                            result += count[a] * (count[a] - 1) // 2 * count[b]
                        else:
                            result += count[a] * count[b] * count[c]

        return result * 6

# Example usage:
# sol = Solution()
# print(sol.singleDivisorTriplet([4, 6, 7, 3, 2]))  # Output: 12
# print(sol.singleDivisorTriplet([1, 2, 2]))        # Output: 6
# print(sol.singleDivisorTriplet([1, 1, 1]))        # Output: 0
```

### Explanation:
1. **Count Frequencies**: We first count the frequency of each number in the array using `Counter`.
2. **Iterate Over Triplets**: We iterate over all possible triplets `(i, j, k)` where `i <= j <= k`. This ensures we do not count permutations multiple times.
3. **Check Divisibility**: For each triplet `(a, b, c)`, we calculate the sum and count how many of `a`, `b`, and `c` divide the sum.
4. **Count Valid Triplets**: If exactly one of the numbers divides the sum, we count the number of such triplets considering the frequency of each number.
5. **Permutations**: Since the problem asks for all permutations of each valid triplet, we multiply the count by 6 (the number of permutations of three distinct elements).

This approach efficiently handles the constraints by leveraging the bounded values of `nums[i]`.

