    def largestVariance(self, s: str) -> int:
        from itertools import permutations

        max_variance = 0
        unique_chars = set(s)

        for x, y in permutations(unique_chars, 2):
            count_x = count_y = 0
            has_x = has_y = False
            for char in s:
                if char == x:
                    count_x += 1
                    has_x = True
                elif char == y:
                    count_y += 1
                    has_y = True

                if count_y > count_x:
                    count_x = count_y = 0
                elif count_x > 0 and count_y > 0:
