  def closestNode(
      self,
      n: int,
      edges: list[list[int]],
      query: list[list[int]],
  ) -> list[int]:
    tree = [[] for _ in range(n)]
    dist = [[-1] * n for _ in range(n)]

    for u, v in edges:
      tree[u].append(v)
      tree[v].append(u)

    def fillDist(start: int, u: int, d: int) -> None:
      dist[start][u] = d
      for v in tree[u]:
        if dist[start][v] == -1:
          fillDist(start, v, d + 1)

    for i in range(n):
      fillDist(i, i, 0)

    def findClosest(u: int, end: int, node: int, ans: int) -> int:
      for v in tree[u]:
        if dist[v][end] < dist[u][end]:
          return findClosest(
              v, end, node, ans if dist[ans][node] < dist[v][node] else v)
      return ans

    return [findClosest(start, end, node, start)
            for start, end, node in query]


Explanation:
To solve this problem, we need to find the closest node on the path from `start` to `end` to a given `node` for each query. The key steps to achieve this are:

1. **Graph Representation**: Represent the tree using an adjacency list.
2. **Finding the Path**: For each query, find the path between `start` and `end`.
3. **Finding the Closest Node**: From the path, determine which node is closest to `node`.

We can use Depth-First Search (DFS) to find the path between two nodes. Additionally, to determine the closest node, we can calculate the shortest path distances from `node` to all other nodes and use these distances to find the closest node on the path.

Here is the complete solution:

```python
from typing import List
from collections import defaultdict, deque

class Solution:
    def closestNode(self, n: int, edges: List[List[int]], query: List[List[int]]) -> List[int]:
        # Build the adjacency list for the tree
        adj_list = defaultdict(list)
        for u, v in edges:
            adj_list[u].append(v)
            adj_list[v].append(u)

        # Helper function to perform DFS and find the path from start to end
        def find_path(start, end):
            stack = [(start, [start])]
            visited = set()
            while stack:
                node, path = stack.pop()
                if node == end:
                    return path
                if node not in visited:
                    visited.add(node)
                    for neighbor in adj_list[node]:
                        if neighbor not in visited:
                            stack.append((neighbor, path + [neighbor]))
            return []

        # Helper function to perform BFS and find shortest path distances from a given node
        def bfs_shortest_distances(start):
            distances = {i: float('inf') for i in range(n)}
            distances[start] = 0
            queue = deque([start])
            while queue:
                node = queue.popleft()
                for neighbor in adj_list[node]:
                    if distances[neighbor] == float('inf'):
                        distances[neighbor] = distances[node] + 1
                        queue.append(neighbor)
            return distances

        # Process each query
        result = []
        for start, end, node in query:
            path = find_path(start, end)
            shortest_distances = bfs_shortest_distances(node)
            closest_node = min(path, key=lambda x: shortest_distances[x])
            result.append(closest_node)

        return result
```

### Explanation:
1. **Graph Representation**: We use an adjacency list to represent the tree.
2. **Finding the Path**: The `find_path` function uses DFS to find the path from `start` to `end`.
3. **Finding the Closest Node**: The `bfs_shortest_distances` function calculates the shortest path distances from `node` to all other nodes using BFS. For each query, we find the node on the path from `start` to `end` that has the minimum distance to `node`.

This solution efficiently handles the constraints and ensures that we find the closest node on the path for each query.

