from typing import List

class TrieNode:
    def __init__(self):
        self.children = {}
        self.prefix_count = 0

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
            node.prefix_count += 1

    def sum_prefix_scores(self, word: str) -> int:
        score = 0
        node = self.root
        for char in word:
            node = node.children[char]
            score += node.prefix_count
        return score

