class Solution:
    def minimumScore(self, s: str, t: str) -> int:
        # Helper function to check if t[left:right+1] can be removed to make t a subsequence of s
        def is_valid_subsequence(left, right):
            # Create a modified version of t with the substring from left to right removed
            modified_t = t[:left] + t[right+1:]
            j = 0  # Pointer for modified_t
            for i in range(len(s)):
                if j < len(modified_t) and s[i] == modified_t[j]:
                    j += 1
                if j == len(modified_t):
                    return True
            return False

        # Calculate the longest prefix of t that is a subsequence of s
        prefix_length = 0
        for i in range(len(s)):
            if prefix_length < len(t) and s[i] == t[prefix_length]:
                prefix_length += 1

        # Calculate the longest suffix of t that is a subsequence of s
        suffix_length = 0
        for i in range(len(s) - 1, -1, -1):
            if suffix_length < len(t) and s[i] == t[len(t) - 1 - suffix_length]:
                suffix_length += 1

        # If t is already a subsequence of s
        if prefix_length == len(t) or suffix_length == len(t):
            return 0

        # Use binary search to find the minimum length of the substring to remove
        left, right = 0, len(t) - 1
        best_score = len(t)

        while left <= right:
            mid = (left + right) // 2
            # Try removing every possible substring of length mid
            found_valid = False
            for start in range(len(t) - mid + 1):
                end = start + mid - 1
                if is_valid_subsequence(start, end):
                    found_valid = True
                    break
            if found_valid:
                best_score = mid
                right = mid - 1
            else:
                left = mid + 1

        return best_score
```

This solution uses a combination of prefix and suffix calculation and binary search to efficiently find the minimum score. It first calculates the longest prefix and suffix of `t` that matches `s`. Then, it uses binary search to determine the smallest length of a substring that can be removed from `t` to make it a subsequence of `s`. The helper function `is_valid_subsequence` checks if a modified version of `t` (with a specific substring removed) is a subsequence of `s`.

class Node:
    def __init__(self):
        self.l = self.r = 0
        self.s = self.lazy = 0


class SegmentTree:
    def __init__(self, nums):
        self.nums = nums
        n = len(nums)
        self.tr = [Node() for _ in range(n << 2)]
        self.build(1, 1, n)

    def build(self, u, l, r):
        self.tr[u].l, self.tr[u].r = l, r
        if l == r:
            self.tr[u].s = self.nums[l - 1]
            return
        mid = (l + r) >> 1
        self.build(u << 1, l, mid)
        self.build(u << 1 | 1, mid + 1, r)
        self.pushup(u)

    def modify(self, u, l, r):
        if self.tr[u].l >= l and self.tr[u].r <= r:
            self.tr[u].lazy ^= 1
            self.tr[u].s = self.tr[u].r - self.tr[u].l + 1 - self.tr[u].s
            return
        self.pushdown(u)
        mid = (self.tr[u].l + self.tr[u].r) >> 1
        if l <= mid:
            self.modify(u << 1, l, r)
        if r > mid:
            self.modify(u << 1 | 1, l, r)
        self.pushup(u)

    def query(self, u, l, r):
        if self.tr[u].l >= l and self.tr[u].r <= r:
            return self.tr[u].s
        self.pushdown(u)
        mid = (self.tr[u].l + self.tr[u].r) >> 1
        res = 0
        if l <= mid:
            res += self.query(u << 1, l, r)
        if r > mid:
            res += self.query(u << 1 | 1, l, r)
        return res

    def pushup(self, u):
        self.tr[u].s = self.tr[u << 1].s + self.tr[u << 1 | 1].s

    def pushdown(self, u):
        if self.tr[u].lazy:
            mid = (self.tr[u].l + self.tr[u].r) >> 1
            self.tr[u << 1].s = mid - self.tr[u].l + 1 - self.tr[u << 1].s
            self.tr[u << 1].lazy ^= 1
            self.tr[u << 1 | 1].s = self.tr[u].r - mid - self.tr[u << 1 | 1].s
            self.tr[u << 1 | 1].lazy ^= 1
            self.tr[u].lazy ^= 1


class Solution:
    def handleQuery(
        self, nums1: List[int], nums2: List[int], queries: List[List[int]]
    ) -> List[int]:
        tree = SegmentTree(nums1)
        s = sum(nums2)
        ans = []
        for op, a, b in queries:
            if op == 1:
                tree.modify(1, a + 1, b + 1)
            elif op == 2:
                s += a * tree.query(1, 1, len(nums1))
            else:
                ans.append(s)
        return ans


