        # Precompute the binary representations of powers of 5 that fit within the given constraints
        powers_of_5 = set()
        power = 1
        while power <= int('1' * 15, 2):  # The maximum possible value for a binary string of length 15
            powers_of_5.add(bin(power)[2:])
            power *= 5

