from typing import List

class Solution:
    def areSimilar(self, mat: List[List[int]], k: int) -> bool:
        m, n = len(mat), len(mat[0])

        for i in range(m):
            if i % 2 == 0:
                # Even-indexed row: cyclically shift to the left
                shifted_row = mat[i][k % n:] + mat[i][:k % n]
            else:
                # Odd-indexed row: cyclically shift to the right
                shifted_row = mat[i][-k % n:] + mat[i][:-k % n]

            if shifted_row != mat[i]:
                return False

        return True
```

This solution iterates over each row of the matrix and applies the appropriate cyclic shift based on whether the row index is even or odd. It then checks if the shifted row matches the original row. If any row does not match after the shifts, it returns `False`. If all rows match, it returns `True`.

