                for y in range(j, j + 3):
                    if x < i + 2 and abs(image[x][y] - image[x + 1][y]) > threshold:
                        return False
                    if y < j + 2 and abs(image[x][y] - image[x][y + 1]) > threshold:
                        return False
            return True

