    def constructTransformedArray(self, nums: List[int]) -> List[int]:
        n = len(nums)
        result = [0] * n

        for i in range(n):
            if nums[i] == 0:
                result[i] = 0
            else:
                # Calculate the new index with circular wrapping
                new_index = (i + nums[i]) % n
                # Adjust for negative steps
                if nums[i] < 0 and new_index > i:
                    new_index -= n
                result[i] = nums[new_index]

