class Solution:
    def permute(self, n: int) -> List[List[int]]:
        def backtrack(arr, path, result):
            if not arr:
                result.append(path)
                return
            for i in range(len(arr)):
                if not path or (path[-1] % 2 == 0 and arr[i] % 2 != 0) or (path[-1] % 2 != 0 and arr[i] % 2 == 0):
